    MaterialInstance = UMaterialInstanceDynamic::Create(LoadObject<UMaterialInterface>(nullptr, TEXT("/Game/Materials/M_4KTexture.M_4KTexture")), this);

    // Assign the material to the static mesh component
    StaticMeshComponent->SetMaterial(0, MaterialInstance);
}

// Handle player input
void AActor::SetupPlayerInputComponent(UInputComponent* PlayerInputComponent)
{
    Super::SetupPlayerInputComponent(PlayerInputComponent);

    UEnhancedInputComponent* EnhancedInputComponent = CastChecked<UEnhancedInputComponent>(PlayerInputComponent);

    // Bind action to switch texture
    EnhancedInputComponent->BindAction(SwitchTextureAction, ETriggerEvent::Triggered, this, &AActor::OnSwitchTexture);
}

void AActor::OnSwitchTexture(const FInputActionValue& Value)
{
    // Load the new texture
    UTexture2D* NewTexture = LoadObject<UTexture2D>(nullptr, TEXT("/Game/Textures/T_4KTexture2.T_4KTexture2"));

    if (NewTexture)
    {
        // Set the new texture parameter in the material instance
        MaterialInstance->SetTextureParameterValue(TEXT("TextureParameter"), NewTexture);
    }
    else

    {
        UE_LOG(LogTemp, Error, TEXT("Failed to load texture"));
    }
}
