Ensuring thread safety in a multi-threaded simulation environment is crucial, especially when dynamically allocating and deallocating memory. Here are some strategies to make your memory allocation thread-safe:

### Thread-Safe Memory Allocation

1. **Mutex Locks**: Use mutex locks to synchronize access to shared resources.
2. **Thread-Safe Functions**: Use thread-safe versions of memory allocation functions.
3. **Memory Pooling**: Implement a thread-safe memory pool to manage memory allocations.

### Example: Using Mutex Locks

Here's an example of how you can use mutex locks to ensure thread safety in memory allocation:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_SIZE 128 * 1024  // Initial chunk size (128KB)
#define GROWTH_FACTOR 2          // Growth factor for each reallocation

typedef struct {
    void* mem;
    size_t current_size;
    size_t total_size;
    pthread_mutex_t lock;
} DynamicMemory;

DynamicMemory* create_dynamic_memory() {
    DynamicMemory* dm = malloc(sizeof(DynamicMemory));
    dm->mem = NULL;
    dm->current_size = 0;
    dm->total_size = 0;
    pthread_mutex_init(&dm->lock, NULL);
    return dm;
}

void* allocate_memory(DynamicMemory* dm) {
    pthread_mutex_lock(&dm->lock);

    if (dm->current_size == 0) {
        dm->current_size = INITIAL_SIZE;
        dm->total_size = dm->current_size;
        dm->mem = malloc(dm->current_size);
    } else {
        dm->current_size *= GROWTH_FACTOR;
        dm->total_size += dm->current_size / GROWTH_FACTOR;
        dm->mem = realloc(dm->mem, dm->current_size);
    }

    pthread_mutex_unlock(&dm->lock);
    return dm->mem;
}

void free_memory(DynamicMemory* dm) {
    pthread_mutex_lock(&dm->lock);

    if (dm->mem) {
        free(dm->mem);
        dm->mem = NULL;
        dm->current_size = 0;
        dm->total_size = 0;
    }

    pthread_mutex_unlock(&dm->lock);
}

void destroy_dynamic_memory(DynamicMemory* dm) {
    free_memory(dm);
    pthread_mutex_destroy(&dm->lock);
    free(dm);
}

// Example usage in a multi-threaded environment
void* thread_function(void* arg) {
    DynamicMemory* dm = (DynamicMemory*)arg;
    void* mem = allocate_memory(dm);
    if (!mem) {
        fprintf(stderr, "Failed to allocate memory\n");
        return NULL;
    }

    // Simulate some operations on the memory
    printf("Thread allocated %zu bytes, total %zu bytes\n", dm->current_size, dm->total_size);

    free_memory(dm);
    return NULL;
}

int main() {
    DynamicMemory* dm = create_dynamic_memory();

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, thread_function, dm);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_dynamic_memory(dm);

    return 0;
}
```

### Explanation

1. **Mutex Initialization**: Initialize a mutex lock to synchronize access to shared memory.
2. **Thread-Safe Allocation**: Use `pthread_mutex_lock` and `pthread_mutex_unlock` to ensure that memory allocation and deallocation are thread-safe.
3. **Thread Function**: Each thread allocates and deallocates memory using the shared `DynamicMemory` structure.

### Memory Pooling with Thread Safety

If you need more fine-grained control over memory allocation and deallocation, consider using a thread-safe memory pool. Here's an example:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    char* pool;
    size_t pool_size;
    size_t next_free;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    pool->pool = malloc(size);
    pool->pool_size = size;
    pool->next_free = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    if (pool->next_free + size > pool->pool_size) {
        fprintf(stderr, "Memory pool exhausted\n");
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    void* ptr = pool->pool + pool->next_free;
    pool->next_free += size;

    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void destroy_memory_pool(MemoryPool* pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->pool);
    free(pool);
}

// Example usage in a multi-threaded environment
void* thread_function(void* arg) {
    MemoryPool* pool = (MemoryPool*)arg;
    void* mem = allocate_from_pool(pool, 100);
    if (!mem) {
        fprintf(stderr, "Failed to allocate memory\n");
        return NULL;
    }

    // Simulate some operations on the memory
    printf("Thread allocated %p from the pool\n", mem);

    return NULL;
}

int main() {
    MemoryPool* pool = create_memory_pool(1024 * 1024);  // 1MB pool

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, thread_function, pool);
    }

    for (int i =  0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_memory_pool(pool);

    return 0;
}
```

### Explanation

1. **Mutex Initialization**: Initialize a mutex lock to synchronize access to the memory pool.
2. **Thread-Safe Allocation**: Use `pthread_mutex_lock` and `pthread_mutex_unlock` to ensure that memory allocation from the pool is thread-safe.
3. **Thread Function**: Each thread allocates memory from the shared pool.

### Summary

By using mutex locks and implementing thread-safe memory allocation and deallocation, you can ensure that your simulation environment remains stable and performs well in a multi-threaded context. This approach helps in managing memory efficiently and avoiding race conditions.

